def extraer_fecha_historica(texto):
    hoy = datetime.now().date()
    if not isinstance(texto, str) or not texto.strip():
        return hoy, "Sin fecha detectada, se usa hoy"

    t = texto.lower()

    if "anteayer" in t:
        return hoy - timedelta(days=2), "Detectado 'anteayer'"
    if "ayer" in t:
        return hoy - timedelta(days=1), "Detectado 'ayer'"
    if "hoy" in t:
        return hoy, "Detectado 'hoy'"

    m_iso = re.search(r"\b(\d{4})-(\d{1,2})-(\d{1,2})\b", t)
    if m_iso:
        y, m, d = map(int, m_iso.groups())
        try:
            return datetime(y, m, d).date(), "Detectada fecha YYYY-MM-DD"
        except ValueError:
            pass

    m_num = re.search(r"\b(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})\b", t)
    if m_num:
        d, m, y = map(int, m_num.groups())
        y = y + 2000 if y < 100 else y
        try:
            return datetime(y, m, d).date(), "Detectada fecha DD/MM/YYYY"
        except ValueError:
            pass

    meses = {
        "enero": 1,
        "febrero": 2,
        "marzo": 3,
        "abril": 4,
        "mayo": 5,
        "junio": 6,
        "julio": 7,
        "agosto": 8,
        "septiembre": 9,
        "setiembre": 9,
        "octubre": 10,
        "noviembre": 11,
        "diciembre": 12,
    }
    m_texto = re.search(r"\b(\d{1,2})\s+de\s+([a-záéíóú]+)(?:\s+de\s+(\d{4}))?\b", t)
    if m_texto:
        d = int(m_texto.group(1))
        mes_txt = m_texto.group(2).replace("á", "a").replace("é", "e").replace("í", "i").replace("ó", "o").replace("ú", "u")
        y = int(m_texto.group(3)) if m_texto.group(3) else hoy.year
        m = meses.get(mes_txt)
        if m:
            try:
                return datetime(y, m, d).date(), "Detectada fecha 'D de mes'"
            except ValueError:
                pass

    dias = {
        "lunes": 0,
        "martes": 1,
        "miercoles": 2,
        "miércoles": 2,
        "jueves": 3,
        "viernes": 4,
        "sabado": 5,
        "sábado": 5,
        "domingo": 6,
    }
    m_dia = re.search(r"\b(lunes|martes|miercoles|miércoles|jueves|viernes|sabado|sábado|domingo)\b(?:\s+(pasado|anterior))?", t)
    if m_dia:
        d_txt = m_dia.group(1)
        q = m_dia.group(2)
        objetivo = dias[d_txt]
        delta = (hoy.weekday() - objetivo) % 7
        if delta == 0:
            delta = 7
        if q in ("pasado", "anterior"):
            delta += 7
        return hoy - timedelta(days=delta), "Detectado día de la semana"

    return hoy, "Sin fecha clara detectada, se usa hoy"


def _clasificar_segmento_diario(texto):
    t = (texto or "").lower()
    kw_running = [
        "carrera", "running", "rodaje", "series", "intervalos", "garmin", "ritmo", "km", "kms",
    ]
    kw_fuerza = [
        "sentadilla", "peso muerto", "dominadas", "jalon", "jalón", "remo", "curl", "press",
        "hip", "bulgara", "búlgar", "predicador", "polea", "repet", "kg",
    ]
    kw_lesion = [
        "dolor", "molest", "inflam", "tibia", "lesion", "lesión", "sobrecarga", "pinchazo",
        "contractura", "me ha costado", "debil", "débil",
    ]

    has_running = any(k in t for k in kw_running)
    has_fuerza = any(k in t for k in kw_fuerza)
    has_lesion = any(k in t for k in kw_lesion)

    if has_running and has_fuerza:
        tipo = "mixto"
    elif has_fuerza:
        tipo = "fuerza"
    elif has_running:
        tipo = "carrera"
    elif has_lesion:
        tipo = "lesion"
    else:
        tipo = "general"

    return {
        "tipo": tipo,
        "has_running": has_running,
        "has_fuerza": has_fuerza,
        "has_lesion": has_lesion,
    }


def _extraer_nota_estado(texto):
    lineas = [l.strip() for l in (texto or "").splitlines() if l.strip()]
    claves = ["dolor", "molest", "inflam", "tibia", "lesion", "lesión", "me ha costado", "costado", "fatiga", "debil", "débil", "cansad"]
    notas = [l for l in lineas if any(k in l.lower() for k in claves)]
    if notas:
        return " | ".join(notas)[:500]
    return ""


def _buscar_actividad_running_fecha(usuario_id, fecha_obj):
    fecha_iso = fecha_obj.strftime("%Y-%m-%d") if hasattr(fecha_obj, "strftime") else str(fecha_obj)
    conn = get_db_connection()
    try:
        q = conn.execute(
            """
            SELECT id_actividad, fecha, distancia_m, ritmo_medio
            FROM actividades_garmin
            WHERE usuario_id = ?
              AND fecha LIKE ?
            ORDER BY distancia_m DESC
            LIMIT 1
            """,
            (usuario_id, f"{fecha_iso}%"),
        ).fetchone()
        if not q:
            return None
        return {
            "id_actividad": q[0],
            "fecha": q[1],
            "distancia_m": q[2],
            "ritmo_medio": q[3],
        }
    except Exception:
        return None
    finally:
        conn.close()


def _inferir_tipo_carrera(texto):
    t = (texto or "").lower()
    if any(k in t for k in ["tirada larga", "larga", "long run", "tl"]):
        return "tirada larga"
    if any(k in t for k in ["series", "interval", "400", "800", "1000", "repeticiones"]):
        return "series"
    if any(k in t for k in ["tempo", "umbral", "threshold"]):
        return "tempo"
    if any(k in t for k in ["cuestas", "cuesta", "hill"]):
        return "cuestas"
    if any(k in t for k in ["fartlek"]):
        return "fartlek"
    if any(k in t for k in ["suave", "recuperacion", "recuperación", "z2", "rodaje"]):
        return "rodaje suave"
    return "rodaje"


